// back rather than rebuilding.\nmodel Deployment {\n  id        String  @id @default(uuid())\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  /// Denormalised from Project so this row is self-sufficient: `storagePrefix`\n  /// is scoped under the owner (matching `tau/project-files/{userId}/…`), and a\n  /// per-user cleanup sweep can list R2 by prefix without a join.\n  userId String\n\n  status DeploymentStatus @default(QUEUED)\n\n  /// R2 prefix holding this build's output, without a trailing slash.\n  storagePrefix String\n\n  /// `Project.headSequence` when the build started: which version of the file\n  /// manifest these bytes were built from.\n  sequence Int @default(0)\n\n  /// The directory inside the sandbox the output was collected from (\"dist\").\n  outputDir String?\n\n  fileCount Int @default(0)\n  sizeBytes Int @default(0)\n\n  /// The DEPLOY job that produced this row. Nullable because the row is created\n  /// before the job is enqueued, in the same transaction that reserves it.\n  jobId String? @unique\n\n  /// What the user needs to told about this build, if anything. `status` says\n  /// how to read it: on FAILED it is why it failed, on READY it is a caveat\n  /// (e.g. the type check was bypassed). One field rather than two because the\n  /// UI shows it in one place either way, and a deployment never has both.\n  error String?\n\n  /// Tail of the build output. Truncated on write — a full build log belongs in\n  /// the job stream, not in a column every list query reads.\n  buildLog String?\n\n  createdAt   DateTime  @default(now())\n  completedAt DateTime?\n\n  /// When this deployment's R2 objects were reclaimed. The row survives — it is\n  /// the history of what was published — but its bytes are gone and it can no\n  /// longer be rolled back to. Set rather than inferred so the sweep can skip\n  /// already-purged rows instead of re-listing an empty prefix every hour.\n  pur